const chatId = $('Telegram Trigger').item.json.message.chat.id.toString();
const message = $('Telegram Trigger').item.json.message.text || '';

// Parse combined sessions and jobs from SSH result
let data = { sessions: {}, jobs: {} };
try { data = JSON.parse($('Get Sessions').item.json.stdout || '{}'); } catch (e) {}
const sessions = data.sessions || {};
const jobs = data.jobs || {};

// Reset session
if (message === '/new' || message === '/reset') {
  return [{ json: { isReset: true, chatId, responseMessage: '🔄 Session reset!', deleteSession: true } }];
}

if (!message.trim()) {
  return [{ json: { isReset: true, chatId, responseMessage: 'Please send a text message.', deleteSession: false } }];
}

// CHECK FOR EXISTING JOB - prevent duplicates
if (jobs[chatId]) {
  return [{ json: { isReset: true, chatId, responseMessage: '⏳ Already processing a request. Please wait for it to complete.', deleteSession: false } }];
}

const sessionId = sessions[chatId] || '';
const outfile = `/tmp/claude-tg-${chatId}-${Date.now()}.txt`;

// Escape message for shell
const safeMessage = message
  .replace(/\\/g, '\\\\')
  .replace(/"/g, '\\"')
  .replace(/`/g, '\\`')
  .replace(/\$/g, '\\$');

return [{
  json: {
    chatId,
    message: safeMessage,
    rawMessage: message,
    sessionId,
    isNewSession: !sessionId,
    outfile,
    isReset: false
  }
}];

const chatId = $('Manage Session').item.json.chatId;
const outfile = $('Manage Session').item.json.outfile;
const sessionId = $('Manage Session').item.json.sessionId || '';
const message = $('Manage Session').item.json.message;
const isNewSession = $('Manage Session').item.json.isNewSession;
const timestamp = Math.floor(Date.now() / 1000);

// Build register command
const registerCmd = `JOBS_FILE=/tmp/claude-telegram-jobs.json
touch "$JOBS_FILE"
if [ ! -s "$JOBS_FILE" ]; then echo '{}' > "$JOBS_FILE"; fi
TMP=$(mktemp)
jq '. + {"${chatId}": {"outfile": "${outfile}", "sessionId": "${sessionId}", "startTime": ${timestamp}, "lastProgress": ""}}' "$JOBS_FILE" > "$TMP" && mv "$TMP" "$JOBS_FILE"
echo "Job registered"`;

// Use wrapper script for real progress updates
let claudeCmd;
if (isNewSession) {
  claudeCmd = `/Users/AhmedE/git/investor-agent/scripts/claude-telegram-wrapper.sh "${message}" "${outfile}" "" ".mcp.json" &`;
} else {
  claudeCmd = `/Users/AhmedE/git/investor-agent/scripts/claude-telegram-wrapper.sh "${message}" "${outfile}" "${sessionId}" ".mcp.json" &`;
}
claudeCmd += '\nsleep 1\necho "Started"';

return [{
  json: {
    chatId,
    outfile,
    sessionId,
    registerCmd,
    claudeCmd
  }
}];
